import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"01 - Frontend Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/architecture.md","filePath":"developers/design-documentation/architecture.md"}'),r={name:"developers/design-documentation/architecture.md"};function s(i,t,n,c,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="_01-frontend-architecture" tabindex="-1">01 - Frontend Architecture <a class="header-anchor" href="#_01-frontend-architecture" aria-label="Permalink to &quot;01 - Frontend Architecture&quot;">​</a></h1><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><p>The frontend is a React 19 TypeScript SPA built with Vite 8. Current package constraints are read from <code>frontend/package.json</code>.</p><table tabindex="0"><thead><tr><th>Concern</th><th>Implementation</th></tr></thead><tbody><tr><td>Routing</td><td><code>react-router</code> 8</td></tr><tr><td>Server state</td><td>TanStack Query 5</td></tr><tr><td>Client state</td><td>Zustand 5</td></tr><tr><td>Styling</td><td>Tailwind CSS 4 and local shadcn-style components</td></tr><tr><td>Icons</td><td>Lucide React</td></tr><tr><td>Forms/editors</td><td>Radix primitives, CodeMirror 6 through <code>@uiw/react-codemirror</code></td></tr><tr><td>Flow canvas</td><td>XYFlow 12</td></tr><tr><td>Charts</td><td>Plotly 3 (<code>plotly.js-dist-min</code>) and Lightweight Charts 5</td></tr><tr><td>Live app events</td><td>Socket.IO client 4</td></tr><tr><td>Language</td><td>TypeScript 7</td></tr><tr><td>Tests</td><td>Vitest 4, Testing Library, axe, Playwright</td></tr><tr><td>Formatting/lint</td><td>Biome 2</td></tr></tbody></table><p>Routing uses the <code>react-router</code> package directly. <code>react-router-dom</code> is no longer a dependency, so imports come from <code>react-router</code>.</p><p>Supported Node versions are <code>&gt;=20.20.0 || &gt;=22.22.0 || &gt;=24.13.0</code>.</p><h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><p><code>frontend/src/main.tsx</code> mounts the app. <code>frontend/src/app/providers.tsx</code> composes TanStack Query, theme, tooltips, Socket.IO, market-data state, and browser toasts. <code>frontend/src/App.tsx</code> lazy-loads route modules and applies public/authenticated/full-width layout boundaries.</p><p>The Flask backend serves the production bundle through <code>blueprints/react_app.py</code> when <code>frontend/dist</code> exists. Vite&#39;s development server runs on port 5173 and proxies backend requests according to <code>frontend/vite.config.ts</code>.</p><h2 id="route-families" tabindex="-1">Route Families <a class="header-anchor" href="#route-families" aria-label="Permalink to &quot;Route Families&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Examples</th></tr></thead><tbody><tr><td>Public/auth</td><td><code>/login</code>, <code>/setup</code>, <code>/reset-password</code>, broker callbacks</td></tr><tr><td>Trading state</td><td><code>/dashboard</code>, <code>/orderbook</code>, <code>/tradebook</code>, <code>/positions</code>, <code>/holdings</code></td></tr><tr><td>Automation</td><td><code>/strategy</code>, <code>/chartink</code>, <code>/python</code>, <code>/flow</code></td></tr><tr><td>Tools</td><td><code>/optionchain</code>, <code>/strategybuilder</code>, <code>/ivchart</code>, <code>/oitracker</code>, <code>/gex</code>, <code>/gammadensity</code>, <code>/oirange</code>, <code>/arbitrage</code>, <code>/scalping</code></td></tr><tr><td>Monitoring</td><td><code>/pnltracker</code>, <code>/latency</code>, <code>/traffic</code>, <code>/health</code>, <code>/security</code></td></tr><tr><td>Admin/integrations</td><td><code>/admin</code>, <code>/apikey</code>, <code>/playground</code>, <code>/telegram</code>, <code>/whatsapp</code></td></tr></tbody></table><p>The exact route list is in <code>frontend/src/App.tsx</code>; navigation visibility is defined separately in <code>frontend/src/config/navigation.ts</code>.</p><h2 id="state-boundaries" tabindex="-1">State Boundaries <a class="header-anchor" href="#state-boundaries" aria-label="Permalink to &quot;State Boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Store/context</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>authStore.ts</code></td><td>User and Tradeboard API key for client calls</td></tr><tr><td><code>brokerStore.ts</code></td><td>Active broker capability metadata</td></tr><tr><td><code>sessionStore.ts</code></td><td>Active app-session count</td></tr><tr><td><code>themeStore.ts</code></td><td>Theme, accent, live/analyzer presentation mode</td></tr><tr><td><code>flowWorkflowStore.ts</code></td><td>Flow editor graph state</td></tr><tr><td><code>MarketDataContext.tsx</code></td><td>Shared market-data manager lifecycle</td></tr></tbody></table><p>TanStack Query owns fetched server data. Zustand is reserved for cross-page client state; feature-local state remains in components.</p><h2 id="data-and-live-updates" tabindex="-1">Data And Live Updates <a class="header-anchor" href="#data-and-live-updates" aria-label="Permalink to &quot;Data And Live Updates&quot;">​</a></h2><p>Feature clients under <code>frontend/src/api/</code> call Flask blueprint or REST resources with credentials. <code>AuthSync</code> reads <code>/auth/session-status</code>, restores user/broker/API-key state, synchronizes analyzer mode, and records the active-session count.</p><p>Market data uses <code>MarketDataManager</code> and hooks such as <code>useLivePrice</code>, <code>useLiveQuote</code>, <code>useMarketData</code>, and <code>useOptionChainLive</code>. Order lifecycle refreshes are triggered by Socket.IO events through <code>useOrderEventRefresh</code>, avoiding high-frequency account polling where an event is available.</p><h2 id="build-and-test-commands" tabindex="-1">Build And Test Commands <a class="header-anchor" href="#build-and-test-commands" aria-label="Permalink to &quot;Build And Test Commands&quot;">​</a></h2><p>Run from <code>frontend/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=chromium</span></span></code></pre></div><p><code>npm run build</code> runs TypeScript project builds before Vite. CI uploads <code>frontend/dist</code>, and main-branch automation rebuilds and commits the production bundle.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>frontend/src/App.tsx</code></td><td>Route graph and lazy modules</td></tr><tr><td><code>frontend/src/app/providers.tsx</code></td><td>Global providers</td></tr><tr><td><code>frontend/src/config/navigation.ts</code></td><td>Sidebar/tool navigation</td></tr><tr><td><code>frontend/src/api/client.ts</code></td><td>Shared HTTP client behavior</td></tr><tr><td><code>frontend/src/components/auth/AuthSync.tsx</code></td><td>Flask session synchronization</td></tr><tr><td><code>frontend/src/lib/MarketDataManager.ts</code></td><td>Shared WebSocket market-data lifecycle</td></tr><tr><td><code>frontend/vite.config.ts</code></td><td>Build and development proxy</td></tr></tbody></table>`,24)])])}const k=e(r,[["render",s]]);export{u as __pageData,k as default};
